import{_ as o,a0 as r,w as p,s as d,I as a,x as e,ao as l,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"8 个基本的 Docker 容器管理命令 | LCTT x X-CMD","titleTemplate":false,"description":"8 个基本的 Docker 容器管理命令 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"8 个基本的 Docker 容器管理命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"8 个基本的 Docker 容器管理命令 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180601 8 basic Docker container management commands","title":"8 个基本的 Docker 容器管理命令","tag":"201806","desc":""},"relativePath":"201806/20180601 8 basic Docker container management commands.md","filePath":"[post].md"}'),c={name:"201806/20180601 8 basic Docker container management commands.md"};function k(u,s,h,b,g,m){const n=r("Link");return p(),d("div",null,[s[27]||(s[27]=a("h1",{id:"_8-个基本的-docker-容器管理命令",tabindex:"-1"},[e("8 个基本的 Docker 容器管理命令 "),a("a",{class:"header-anchor",href:"#_8-个基本的-docker-容器管理命令","aria-label":"Permalink to “8 个基本的 Docker 容器管理命令”"},"​")],-1)),s[28]||(s[28]=a("blockquote",null,[a("p",null,"利用这 8 个命令可以学习 Docker 容器的基本管理方式。这是一个为 Docker 初学者准备的，带有示范命令输出的指南。")],-1)),s[29]||(s[29]=a("p",null,[a("img",{src:"https://a4.kerneltalks.com/wp-content/uploads/2018/06/basic-Docker-container-management-commands.png",alt:"Docker 容器管理命令"})],-1)),a("p",null,[s[2]||(s[2]=l("在这篇文章中，我们将带你学习 8 个基本的 Docker 容器命令，它们操控着 Docker 容器的基本活动，例如 <ruby>运行<rt>run</rt></ruby>、 <ruby>列举<rt>list</rt></ruby>、 <ruby>停止<rt>stop</rt></ruby>、 查看<ruby>历史纪录<rt>logs</rt></ruby>、 <ruby>删除<rt>delete</rt></ruby> 等等。如果你对 Docker 的概念很陌生，推荐你看看我们的 ",11)),t(n,{href:"https://kerneltalks.com/virtualization/what-is-docker-introduction-guide-to-docker/"},{default:i(()=>[...s[0]||(s[0]=[e("介绍指南",-1)])]),_:1}),s[3]||(s[3]=e("，来了解 Docker 的基本内容以及 ",-1)),t(n,{href:"https://kerneltalks.com/virtualization/how-to-install-docker-in-linux/"},{default:i(()=>[...s[1]||(s[1]=[e("如何",-1)])]),_:1}),s[4]||(s[4]=e(" 在 Linux 上安装 Docker。 现在让我们赶快进入要了解的命令：",-1))]),s[30]||(s[30]=a("h3",{id:"如何运行-docker-容器",tabindex:"-1"},[e("如何运行 Docker 容器？ "),a("a",{class:"header-anchor",href:"#如何运行-docker-容器","aria-label":"Permalink to “如何运行 Docker 容器？”"},"​")],-1)),a("p",null,[s[6]||(s[6]=e("众所周知，Docker 容器只是一个运行于",-1)),s[7]||(s[7]=a("ruby",null,[e("宿主操作系统"),a("rt",null,"host OS")],-1)),s[8]||(s[8]=e("上的应用进程，所以你需要一个镜像来运行它。Docker 镜像以进程的方式运行时就叫做 Docker 容器。你可以加载本地 Docker 镜像，也可以从 Docker Hub 上下载。Docker Hub 是一个提供公有和私有镜像来进行",-1)),s[9]||(s[9]=a("ruby",null,[e("拉取"),a("rt",null,"pull")],-1)),s[10]||(s[10]=e("操作的集中仓库。官方的 Docker Hub 位于 ",-1)),t(n,{href:"https://hub.docker.com/"},{default:i(()=>[...s[5]||(s[5]=[e("hub.docker.com",-1)])]),_:1}),s[11]||(s[11]=e("。 当你指示 Docker 引擎运行容器时，它会首先搜索本地镜像，如果没有找到，它会从 Docker Hub 上拉取相应的镜像。",-1))]),s[31]||(s[31]=l(`<p>让我们运行一个 Apache web 服务器的 Docker 镜像，比如 httpd 进程。你需要运行 <code>docker container run</code> 命令。旧的命令为 <code>docker run</code>， 但后来 Docker 添加了子命令部分，所以新版本支持下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container run -d -p 80:80 httpd</span></span>
<span class="line"><span>Unable to find image &#39;httpd:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from library/httpd</span></span>
<span class="line"><span>3d77ce4481b1: Pull complete</span></span>
<span class="line"><span>73674f4d9403: Pull complete</span></span>
<span class="line"><span>d266646f40bd: Pull complete</span></span>
<span class="line"><span>ce7b0dda0c9f: Pull complete</span></span>
<span class="line"><span>01729050d692: Pull complete</span></span>
<span class="line"><span>014246127c67: Pull complete</span></span>
<span class="line"><span>7cd2e04cf570: Pull complete</span></span>
<span class="line"><span>Digest: sha256:f4610c3a1a7da35072870625733fd0384515f7e912c6223d4a48c6eb749a8617</span></span>
<span class="line"><span>Status: Downloaded newer image for httpd:latest</span></span>
<span class="line"><span>c46f2e9e4690f5c28ee7ad508559ceee0160ac3e2b1688a61561ce9f7d99d682</span></span></code></pre></div><p>Docker 的 <code>run</code> 命令将镜像名作为强制参数，另外还有很多可选参数。常用的参数有：</p><ul><li><code>-d</code>：从当前 shell 脱离容器</li><li><code>-p X:Y</code>：绑定容器的端口 Y 到宿主机的端口 X</li><li><code>--name</code>：命名你的容器。如果未指定，它将被赋予随机生成的名字</li><li><code>-e</code>：当启动容器时传递环境编辑及其值</li></ul><p>通过以上输出你可以看到，我们将 <code>httpd</code> 作为镜像名来运行容器。接着，本地镜像没有找到，Docker 引擎从 Docker Hub 拉取了它。注意，它下载了镜像 <code>httpd:latest</code>， 其中 <code>:</code> 后面跟着版本号。如果你需要运行特定版本的容器，你可以在镜像名后面注明版本名。如果不提供版本名，Docker 引擎会自动拉取最新的版本。</p><p>输出的最后一行显示了你新运行的 httpd 容器的唯一 ID。</p><h3 id="如何列出所有运行中的-docker-容器" tabindex="-1">如何列出所有运行中的 Docker 容器？ <a class="header-anchor" href="#如何列出所有运行中的-docker-容器" aria-label="Permalink to “如何列出所有运行中的 Docker 容器？”">​</a></h3><p>现在，你的容器已经运行起来了，你可能想要确认这一点，或者你想要列出你的机器上运行的所有容器。你可以使用 <code>docker container ls</code> 命令。在旧的 Docker 版本中，对应的命令为 <code>docker ps</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container ls</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND              CREATED             STATUS              PORTS                NAMES</span></span>
<span class="line"><span>c46f2e9e4690        httpd               &quot;httpd-foreground&quot;   11 minutes ago      Up 11 minutes       0.0.0.0:80-&gt;80/tcp   cranky_cori</span></span></code></pre></div><p>列出的结果是按列显示的。每一列的值分别为：</p><ol><li>Container ID ：一开始的几个字符对应你的容器的唯一 ID</li><li>Image ：你运行容器的镜像名</li><li>Command ：容器启动后运行的命令</li><li>Created ：创建时间</li><li>Status ：容器当前状态</li><li>Ports ：与宿主端口相连接的端口信息</li><li>Names ：容器名（如果你没有命名你的容器，那么会随机创建）</li></ol><h3 id="如何查看-docker-容器的历史纪录" tabindex="-1">如何查看 Docker 容器的历史纪录？ <a class="header-anchor" href="#如何查看-docker-容器的历史纪录" aria-label="Permalink to “如何查看 Docker 容器的历史纪录？”">​</a></h3><p>在第一步我们使用了 <code>-d</code> 参数来将容器，在它一开始运行的时候，就从当前的 shell 中脱离出来。在这种情况下，我们不知道容器里面发生了什么。所以为了查看容器的历史纪录，Docker 提供了 <code>logs</code> 命令。它采用容器名称或 ID 作为参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container logs cranky_cori</span></span>
<span class="line"><span>AH00558: httpd: Could not reliably determine the server&#39;s fully qualified domain name, using 172.17.0.2. Set the &#39;ServerName&#39; directive globally to suppress this message</span></span>
<span class="line"><span>AH00558: httpd: Could not reliably determine the server&#39;s fully qualified domain name, using 172.17.0.2. Set the &#39;ServerName&#39; directive globally to suppress this message</span></span>
<span class="line"><span>[Thu May 31 18:35:07.301158 2018] [mpm_event:notice] [pid 1:tid 139734285989760] AH00489: Apache/2.4.33 (Unix) configured -- resuming normal operations</span></span>
<span class="line"><span>[Thu May 31 18:35:07.305153 2018] [core:notice] [pid 1:tid 139734285989760] AH00094: Command line: &#39;httpd -D FOREGROUND&#39;</span></span></code></pre></div><p>这里我使用了容器名称作为参数。你可以看到在我们的 httpd 容器中与 Apache 相关的历史纪录。</p><h3 id="如何确定-docker-容器的进程" tabindex="-1">如何确定 Docker 容器的进程？ <a class="header-anchor" href="#如何确定-docker-容器的进程" aria-label="Permalink to “如何确定 Docker 容器的进程？”">​</a></h3><p>容器是一个使用宿主资源来运行的进程。这样，你可以在宿主系统的进程表中定位容器的进程。让我们在宿主系统上确定容器进程。</p><p>Docker 使用著名的 <code>top</code> 命令作为子命令的名称，来查看容器产生的进程。它采用容器的名称或 ID 作为参数。在旧版本的 Docker 中，只可运行 <code>docker top</code> 命令。在新版本中，<code>docker top</code> 和 <code>docker container top</code> 命令都可以生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container top  cranky_cori</span></span>
<span class="line"><span>UID                 PID                 PPID                C                   STIME               TTY                 TIME                CMD</span></span>
<span class="line"><span>root                15702               15690               0                   18:35               ?                   00:00:00            httpd -DFOREGROUND</span></span>
<span class="line"><span>bin                 15729               15702               0                   18:35               ?                   00:00:00            httpd -DFOREGROUND</span></span>
<span class="line"><span>bin                 15730               15702               0                   18:35               ?                   00:00:00            httpd -DFOREGROUND</span></span>
<span class="line"><span>bin                 15731               15702               0                   18:35               ?                   00:00:00            httpd -DFOREGROUND</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>root@kerneltalks # ps -ef |grep -i 15702</span></span>
<span class="line"><span>root     15702 15690  0 18:35 ?        00:00:00 httpd -DFOREGROUND</span></span>
<span class="line"><span>bin      15729 15702  0 18:35 ?        00:00:00 httpd -DFOREGROUND</span></span>
<span class="line"><span>bin      15730 15702  0 18:35 ?        00:00:00 httpd -DFOREGROUND</span></span>
<span class="line"><span>bin      15731 15702  0 18:35 ?        00:00:00 httpd -DFOREGROUND</span></span>
<span class="line"><span>root     15993 15957  0 18:59 pts/0    00:00:00 grep --color=auto -i 15702</span></span></code></pre></div><p>在第一个输出中，列出了容器产生的进程的列表。它包含了所有细节，包括<ruby>用户号<rt>uid</rt></ruby>、<ruby>进程号<rt>pid</rt></ruby>，<ruby>父进程号<rt>ppid</rt></ruby>、开始时间、命令，等等。这里所有的进程号你都可以在宿主的进程表里搜索到。这就是我们在第二个命令里做得。这证明了容器确实是宿主系统中的进程。</p><h3 id="如何停止-docker-容器" tabindex="-1">如何停止 Docker 容器？ <a class="header-anchor" href="#如何停止-docker-容器" aria-label="Permalink to “如何停止 Docker 容器？”">​</a></h3><p>只需要 <code>stop</code> 命令！同样，它采用容器名称或 ID 作为参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container stop cranky_cori</span></span>
<span class="line"><span>cranky_cori</span></span></code></pre></div><h3 id="如何列出停止的或不活动的-docker-容器" tabindex="-1">如何列出停止的或不活动的 Docker 容器？ <a class="header-anchor" href="#如何列出停止的或不活动的-docker-容器" aria-label="Permalink to “如何列出停止的或不活动的 Docker 容器？”">​</a></h3><p>现在我们停止了我们的容器，这时如果我们使用 <code>ls</code> 命令，它将不会出现在列表中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container ls</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND             CREATED             STATUS              PORTS               NAMES</span></span></code></pre></div><p>所以，在这种情况下，如果想要查看停止的或不活动的容器，你需要在 <code>ls</code> 命令里同时使用 <code>-a</code> 参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container ls -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND              CREATED             STATUS                     PORTS               NAMES</span></span>
<span class="line"><span>c46f2e9e4690        httpd               &quot;httpd-foreground&quot;   33 minutes ago      Exited (0) 2 minutes ago                       cranky_cori</span></span></code></pre></div><p>有了 <code>-a</code> 参数，现在我们可以查看已停止的容器。注意这些容器的状态被标注为 <ruby>已退出<rt>exited</rt></ruby>。既然容器只是一个进程，那么用“退出”比“停止”更合适！</p><h3 id="如何-重新-启动-docker-容器" tabindex="-1">如何（重新）启动 Docker 容器？ <a class="header-anchor" href="#如何-重新-启动-docker-容器" aria-label="Permalink to “如何（重新）启动 Docker 容器？”">​</a></h3><p>现在，我们来启动这个已停止的容器。这和运行一个容器有所区别。当你运行一个容器时，你将启动一个全新的容器。当你启动一个容器时，你将开始一个已经停止并保存了当时运行状态的容器。它将以停止时的状态重新开始运行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks #  docker container start c46f2e9e4690</span></span>
<span class="line"><span>c46f2e9e4690</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>root@kerneltalks # docker container ls -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND              CREATED             STATUS              PORTS                NAMES</span></span>
<span class="line"><span>c46f2e9e4690        httpd               &quot;httpd-foreground&quot;   35 minutes ago      Up 8 seconds        0.0.0.0:80-&gt;80/tcp   cranky_cori</span></span></code></pre></div><h3 id="如何移除-docker-容器" tabindex="-1">如何移除 Docker 容器？ <a class="header-anchor" href="#如何移除-docker-容器" aria-label="Permalink to “如何移除 Docker 容器？”">​</a></h3><p>我们使用 <code>rm</code> 命令来移除容器。你不可以移除运行中的容器。移除之前需要先停止容器。你可以使用 <code>-f</code> 参数搭配 <code>rm</code> 命令来强制移除容器，但并不推荐这么做。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # docker container rm cranky_cori</span></span>
<span class="line"><span>cranky_cori</span></span>
<span class="line"><span>root@kerneltalks # docker container ls -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE               COMMAND             CREATED             STATUS              PORTS               NAMES</span></span></code></pre></div><p>你看，一旦移除了容器，即使再使用 <code>ls -a</code> 命令也查看不到容器了。</p><hr>`,37)),a("p",null,[s[13]||(s[13]=e("via: ",-1)),t(n,{href:"https://kerneltalks.com/virtualization/8-basic-docker-container-management-commands/"},{default:i(()=>[...s[12]||(s[12]=[e("https://kerneltalks.com/virtualization/8-basic-docker-container-management-commands/",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("作者：",-1)),t(n,{href:"https://kerneltalks.com"},{default:i(()=>[...s[14]||(s[14]=[e("Shrikant Lavhate",-1)])]),_:1}),s[19]||(s[19]=e(" 选题：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[15]||(s[15]=[e("lujun9972",-1)])]),_:1}),s[20]||(s[20]=e(" 译者：",-1)),t(n,{href:"https://github.com/lonaparte"},{default:i(()=>[...s[16]||(s[16]=[e("lonaparte",-1)])]),_:1}),s[21]||(s[21]=e(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[17]||(s[17]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=e("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[22]||(s[22]=[e("LCTT",-1)])]),_:1}),s[25]||(s[25]=e(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[23]||(s[23]=[e("Linux中国",-1)])]),_:1}),s[26]||(s[26]=e(" 荣誉推出",-1))])])}const T=o(c,[["render",k]]);export{y as __pageData,T as default};
